// Loop over input items and get the data we need
var contactArrLength = $input.all()[0].json.contacts.length;
var contactArr = contactArrLength > 0 ? $input.all()[0].json.contacts[0].customFields : [];
function findValueById(arr, id) {
  let result;
  arr.forEach(item => {
    if (Array.isArray(item)) {
      result = findValueById(item, id);
    } else if (item.id === id) {
      result = item.value;
    }
  });
  return result;
}

// Extract the values we need
var call1 = contactArrLength > 0 ? findValueById(contactArr, "KeAqFtPCLbvwmfFTQYQe") : "";
var call2 = contactArrLength > 0 ? findValueById(contactArr, "yNW5UyI2UeXaMMEUEoNj") : "";
var call3 = contactArrLength > 0 ? findValueById(contactArr, "CDyptcCL0687sSwxgOYB") : "";
var chat = contactArrLength > 0 ? findValueById(contactArr, "d1E7AQI1N9V6lyzdB4qw") : "";
var reactiveCallHistory = contactArrLength > 0 ? findValueById(contactArr, "jr9ZXook1RcVoGmiuqTp") : "";
var contactName = contactArrLength > 0 ? $input.all()[0].json.contacts[0].contactName : "customer";

// Use the webhook response as a template object
var template = {
  "call_inbound": {
    "override_agent_id": "agent_191599fb3ce849161ad14a64b8",
    "override_agent_version": "13",
    "dynamic_variables": {
      "contact_name": contactName,
      "call1": call1 || "",
      "call2": call2 || "",
      "call3": call3 || "",
      "chat": chat || "",
      "reactiveCallHistory": reactiveCallHistory || ""
    }
  }
};

// Convert to string first with standard JSON.stringify
var jsonString = JSON.stringify(template);

// Then convert back to object and return that
// This ensures proper escaping of all values
return JSON.parse(jsonString);

